/* =============================================================================
   INVT-01 · Las dos tablas. Ningún color literal: todo de tokens.css.
   ========================================================================== */

.sectionTitle {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  margin: 28px 0 10px;
}

.wrap {
  overflow-x: auto;
  border: 1px solid var(--bw-line-steel);
  border-radius: 5px;
  margin-bottom: 8px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.th {
  background: var(--bw-surface-mist);
  padding: 9px 14px;
  text-align: left;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.td {
  padding: 11px 14px;
  border-bottom: 1px solid var(--bw-divider-mist);
  color: var(--bw-ink-steel);
  vertical-align: middle;
}

.table tbody tr:last-child .td {
  border-bottom: none;
}

.table tbody tr:hover .td {
  background: var(--bw-row-hover-tint);
}

/* Va después de `.td` a propósito: con la misma especificidad, el orden manda. */
.mono {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.daysPending {
  color: var(--bw-brass);
}

/* ── Insignias ─────────────────────────────────────────────────────────── */

.badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
  white-space: nowrap;
}

.badgePending {
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  color: var(--bw-primary-dark);
}

.badgeAccepted {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.badgeExpired {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-ink-steel-soft);
}

.badgeAdmin {
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border-strong);
  color: var(--bw-warning-dark);
}

.badgeEditor {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-ink-steel-soft);
}

.badgeActive {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.badgeSuspended {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-error-text);
}

/* ── Fila vacía y acciones ─────────────────────────────────────────────── */

.emptyCell {
  padding: 16px 14px;
  text-align: center;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.actionButton {
  padding: 4px 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: border-color 0.15s, color 0.15s, background 0.15s;
}

.actionButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-warning-dark);
}

.actionButton:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.actionDanger {
  border-color: var(--bw-badge-danger-border);
  background: var(--bw-danger-hover-bg);
  color: var(--bw-error-text);
}

.actionDanger:hover:not(:disabled) {
  border-color: var(--bw-danger);
  background: var(--bw-tint-danger);
  color: var(--bw-error-text);
}

.none {
  font-size: 12px;
  color: var(--bw-line-steel-strong);
}

import {
  CANNOT_REMOVE_OWN_ADMIN,
  canRemove,
  expiresInLabel,
  memberStateLabel,
  roleLabel,
  sentAtLabel,
  type InvitationRow,
  type InvitationStatus,
  type TeamMember,
} from '../../lib/invitations';
import styles from './InvitationTables.module.css';

interface Props {
  invitations: InvitationRow[];
  team: TeamMember[];
  selfId: string;
  busy: boolean;
  onResend: (invitationId: string) => void;
  onRemove: (member: TeamMember) => void;
}

/**
 * Las dos tablas de INVT-01. Presentacional puro: no toca la red y no guarda
 * estado. Quién puede reenviar y quién puede eliminarse lo decide
 * `lib/invitations` (`canRemove`), no una condición escrita aquí.
 *
 * `onRemove` recibe el MIEMBRO ENTERO, no su id: el diálogo de confirmación
 * necesita el nombre y el email para decir a quién va a dejar sin acceso.
 */
export function InvitationTables({
  invitations,
  team,
  selfId,
  busy,
  onResend,
  onRemove,
}: Props) {
  return (
    <>
      <section>
        <h2 className={styles.sectionTitle}>Invitaciones enviadas</h2>
        <div className={styles.wrap}>
          <table className={styles.table} aria-label="Invitaciones enviadas">
            <thead>
              <tr>
                <th scope="col" className={styles.th}>
                  Email
                </th>
                <th scope="col" className={styles.th}>
                  Estado
                </th>
                <th scope="col" className={styles.th}>
                  Fecha de envío
                </th>
                <th scope="col" className={styles.th}>
                  Expira en
                </th>
                <th scope="col" className={styles.th}>
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody>
              {invitations.length === 0 ? (
                <tr>
                  <td className={styles.emptyCell} colSpan={5}>
                    Todavía no has enviado ninguna invitación.
                  </td>
                </tr>
              ) : (
                invitations.map((invitation) => (
                  <tr key={invitation.id}>
                    <td className={`${styles.td} ${styles.mono}`}>{invitation.email}</td>
                    <td className={styles.td}>
                      <span className={`${styles.badge} ${STATUS_CLASS[invitation.status]}`}>
                        {invitation.status}
                      </span>
                    </td>
                    <td className={`${styles.td} ${styles.mono}`}>
                      {sentAtLabel(invitation.sentAt)}
                    </td>
                    {/* Los días solo tienen sentido mientras la invitación
                        espera: en brass si es una pendiente. */}
                    <td
                      className={
                        invitation.status === 'Pendiente'
                          ? `${styles.td} ${styles.mono} ${styles.daysPending}`
                          : `${styles.td} ${styles.mono}`
                      }
                    >
                      {expiresInLabel(invitation.daysLeft)}
                    </td>
                    <td className={styles.td}>
                      {invitation.status === 'Expirada' ? (
                        <button
                          type="button"
                          className={styles.actionButton}
                          aria-label={`Reenviar ${invitation.email}`}
                          disabled={busy}
                          onClick={() => onResend(invitation.id)}
                        >
                          Reenviar
                        </button>
                      ) : (
                        <span className={styles.none}>—</span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </section>

      <section>
        <h2 className={styles.sectionTitle}>Usuarios activos</h2>
        <div className={styles.wrap}>
          <table className={styles.table} aria-label="Usuarios activos">
            <thead>
              <tr>
                <th scope="col" className={styles.th}>
                  Nombre
                </th>
                <th scope="col" className={styles.th}>
                  Email
                </th>
                <th scope="col" className={styles.th}>
                  Rol
                </th>
                <th scope="col" className={styles.th}>
                  Estado
                </th>
                <th scope="col" className={styles.th}>
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody>
              {team.map((member) => (
                <tr key={member.id}>
                  <td className={styles.td}>{member.fullName}</td>
                  <td className={`${styles.td} ${styles.mono}`}>{member.email}</td>
                  <td className={styles.td}>
                    <span
                      className={
                        member.role === 'ADMIN'
                          ? `${styles.badge} ${styles.badgeAdmin}`
                          : `${styles.badge} ${styles.badgeEditor}`
                      }
                    >
                      {roleLabel(member.role)}
                    </span>
                  </td>
                  <td className={styles.td}>
                    <span
                      className={
                        member.state === 'SUSPENDED'
                          ? `${styles.badge} ${styles.badgeSuspended}`
                          : `${styles.badge} ${styles.badgeActive}`
                      }
                    >
                      {memberStateLabel(member.state)}
                    </span>
                  </td>
                  <td className={styles.td}>
                    {canRemove(member, selfId) ? (
                      <button
                        type="button"
                        className={`${styles.actionButton} ${styles.actionDanger}`}
                        aria-label={`Eliminar ${member.fullName}`}
                        disabled={busy}
                        onClick={() => onRemove(member)}
                      >
                        Eliminar
                      </button>
                    ) : (
                      /* Un guion con el motivo: una acción que no está dice por
                         qué no está. */
                      <span
                        className={styles.none}
                        title={
                          member.id === selfId ? CANNOT_REMOVE_OWN_ADMIN : CANNOT_REMOVE_OTHER
                        }
                      >
                        —
                      </span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </>
  );
}

// -----------------------------------------------------------------------------
// Constantes de presentación
// -----------------------------------------------------------------------------

const STATUS_CLASS: Record<InvitationStatus, string> = {
  Pendiente: styles.badgePending,
  Aceptada: styles.badgeAccepted,
  Expirada: styles.badgeExpired,
};

/** El motivo del guion cuando la fila no es la propia y aun así no se puede borrar. */
const CANNOT_REMOVE_OTHER = 'Solo se pueden eliminar usuarios con rol Editor';

