/* =============================================================================
   INVT-01 · Panel de Gestión de Invitaciones — estilos de la pantalla.

   Ningún color literal: todo sale de tokens.css. Donde el HTML aprobado usa
   blanco puro (#fff) se usa --bw-warm-cream, que es la superficie más clara de
   la paleta: el sistema no tiene token de blanco y no se inventa uno.
   ========================================================================== */

/* La raíz de la pantalla es hija DIRECTA de .bwcnt, que es `overflow: hidden`:
   el scroll es de la pantalla (F-186/F-189), no del panel. Mismo patrón que
   `.page` de Directory.module.css. */
.screen {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  padding: 40px var(--bw-pad-panel) 56px;
}

/* El ancho de lectura del HTML aprobado. Va en un contenedor propio y no en
   `.screen` para no encoger el fondo del modal, que es `position: fixed`. */
.content {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
}

/* ── Cabecera ──────────────────────────────────────────────────────────── */

.eyebrow {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-brass);
  margin: 0 0 8px;
}

.title {
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: 22px;
  letter-spacing: var(--bw-ls-title);
  line-height: 1.25;
  color: var(--bw-deep-steel);
  margin: 0 0 4px;
}

.subtitle {
  font-size: 14px;
  line-height: 1.5;
  color: var(--bw-steel-mist);
  margin: 0 0 28px;
}

.subtitle strong {
  color: var(--bw-deep-steel);
  font-weight: 600;
}

/* ── Indicador de capacidad ────────────────────────────────────────────── */

.capacityRow {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  margin-bottom: 20px;
}

.dots {
  display: flex;
  gap: 5px;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bw-line-steel);
  transition: background 0.2s;
}

.dotUsed {
  background: var(--bw-deep-steel);
}

.dotInv {
  background: var(--bw-brass);
}

.dotFree {
  background: var(--bw-line-steel);
}

.count {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  font-weight: 600;
  color: var(--bw-deep-steel);
}

.detail {
  font-size: 12px;
  color: var(--bw-steel-mist);
}

/* ── Aviso de límite (brass tenue, con icono) ──────────────────────────── */

.notice {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border-strong);
  border-radius: 4px;
  padding: 12px 14px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-deep-steel);
  margin: 0 0 28px;
}

.noticeIcon {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--bw-brass);
}

/* ── Tarjeta de invitación ─────────────────────────────────────────────── */

.card {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 6px;
  padding: 20px 22px;
  margin-bottom: 28px;
}

.cardTitle {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 13px;
  color: var(--bw-deep-steel);
  margin: 0 0 12px;
}

.inviteRow {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.input {
  flex: 1;
  min-width: 0;
  padding: var(--bw-pad-input);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 14px;
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input::placeholder {
  color: var(--bw-input-placeholder);
}

.input:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.input:disabled {
  background: var(--bw-cold-white);
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.button {
  padding: 10px 18px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.15s;
}

.button:hover:not(:disabled) {
  opacity: 0.9;
}

.button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.fieldError {
  font-size: 12px;
  color: var(--bw-error-text);
  margin: 4px 0 0;
}

.feedbackOk {
  font-size: 12px;
  color: var(--bw-success-dark);
  margin: 4px 0 0;
}

.feedbackError {
  font-size: 12px;
  color: var(--bw-error-text);
  margin: 4px 0 0;
}

/* ── Estados de la pantalla entera ─────────────────────────────────────── */

.status {
  font-size: 14px;
  color: var(--bw-steel-mist);
  padding: 24px 0;
}

.alert {
  font-size: 14px;
  color: var(--bw-error-text);
  padding: 24px 0;
}

