import { useEffect, useState, type ChangeEvent } from 'react';
import {
  LIMIT_NOTICE,
  capacityDetail,
  capacityDots,
  capacityLabel,
  emailHasAccount,
  fetchInvitations,
  fetchTeam,
  inviteMember,
  isValidEmail,
  limitReached,
  removeMember,
  resendInvitation,
  type CapacityDot,
  type InvitationRow,
  type TeamMember,
} from '../../lib/invitations';
import { errorMessage, type MemberProfile } from '../../lib/session';
import { InvitationTables } from './InvitationTables';
import { RemoveMemberDialog } from './RemoveMemberDialog';
import styles from './Invitations.module.css';

interface Props {
  profile: MemberProfile;
}

/**
 * INV-01 · Panel de Gestión de Invitaciones (Módulo 01 · Onboarding).
 *
 * Es la PANTALLA: posee todo el estado y es el único sitio que llama a la red.
 * `InvitationTables` y `RemoveMemberDialog` son presentacionales.
 *
 * El servidor manda: el límite de 5, «este email ya tiene cuenta» y quién puede
 * qué los hace cumplir `0037`. Aquí solo se pinta lo que `lib/invitations`
 * calcula, sin una segunda opinión sobre lo que el servidor ya decidió.
 *
 * ⚠ Lo que esta pantalla NO hace, aunque el HTML aprobado lo insinúe: no envía
 * ningún correo (no hay proveedor en el proyecto ni flujo de registro por
 * invitación). La invitación queda REGISTRADA y eso es lo que dice el mensaje.
 * Tampoco reproduce los botones de demo del prototipo ni el chat de VERA.
 */
export function Invitations({ profile }: Props) {
  /**
   * El rol se lee, no se asume: la propia spec dice que solo el ADMIN ve esta
   * pantalla. Los hooks se declaran SIEMPRE (regla de los hooks); los efectos
   * salen sin hacer nada si no es ADMIN.
   */
  const isAdmin = profile.role === 'ADMIN';

  const [team, setTeam] = useState<TeamMember[]>([]);
  const [invitations, setInvitations] = useState<InvitationRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [email, setEmail] = useState('');
  const [checking, setChecking] = useState(false);
  /**
   * El resultado de `emailHasAccount` va JUNTO AL TEXTO al que corresponde. Una
   * respuesta que llegue cuando el campo ya dice otra cosa se ignora: si no, el
   * aviso «ya tiene cuenta» parpadearía bajo un email que no es el suyo.
   */
  const [accountCheck, setAccountCheck] = useState<{ email: string; hasAccount: boolean } | null>(
    null,
  );
  const [sending, setSending] = useState(false);
  const [feedback, setFeedback] = useState<{ tone: 'ok' | 'error'; text: string } | null>(null);

  /** Reenvío o eliminación en vuelo: bloquea las acciones de las dos tablas. */
  const [busy, setBusy] = useState(false);
  const [pendingMember, setPendingMember] = useState<TeamMember | null>(null);
  const [removeError, setRemoveError] = useState<string | null>(null);

  /**
   * La carga: las dos listas EN PARALELO y en el mismo efecto. Si cualquiera de
   * las dos rechaza, la pantalla entera es un error: media pantalla con datos y
   * media vacía daría una idea falsa de cuántas plazas quedan.
   */
  useEffect(() => {
    if (!isAdmin) return;

    let cancelled = false;

    setLoading(true);
    setLoadError(null);

    Promise.all([fetchTeam(profile.orgId), fetchInvitations()])
      .then(([members, rows]) => {
        if (cancelled) return;
        setTeam(members);
        setInvitations(rows);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setTeam([]);
        setInvitations([]);
        setLoadError(errorMessage(toError(err)));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [isAdmin, profile.orgId]);

  /**
   * La comprobación en tiempo real, SIN debounce (spec §3). Solo se lanza con un
   * email con forma válida: preguntar por «a» no informa de nada y gasta una
   * llamada por pulsación.
   *
   * Si `emailHasAccount` rechaza se trata como «no se sabe»: NO se bloquea el
   * envío, porque el servidor lo comprobará igual y un fallo de red no puede
   * dejar al ADMIN sin poder invitar.
   */
  useEffect(() => {
    if (!isAdmin) return;

    const text = email;

    if (!isValidEmail(text)) {
      setChecking(false);
      setAccountCheck(null);
      return;
    }

    let cancelled = false;
    setChecking(true);

    emailHasAccount(text)
      .then((hasAccount) => {
        if (cancelled) return;
        setAccountCheck({ email: text, hasAccount });
      })
      .catch(() => {
        if (cancelled) return;
        setAccountCheck(null);
      })
      .finally(() => {
        if (!cancelled) setChecking(false);
      });

    return () => {
      cancelled = true;
    };
  }, [email, isAdmin]);

  /** Vuelve a traer las dos listas tras una acción que cambió lo que hay. */
  async function refresh() {
    try {
      const [members, rows] = await Promise.all([fetchTeam(profile.orgId), fetchInvitations()]);
      setTeam(members);
      setInvitations(rows);
    } catch {
      // La recarga no forma parte del resultado de la acción: si falla, la
      // pantalla se queda con lo que ya tenía y no se inventa un error nuevo.
    }
  }

  /** Cualquier cambio del texto borra el mensaje anterior (spec §3). */
  function handleEmailChange(event: ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    setFeedback(null);
  }

  async function handleSend() {
    if (sending) return;

    setFeedback(null);
    setSending(true);

    try {
      await inviteMember(email);
    } catch (err: unknown) {
      setSending(false);
      // El campo NO se vacía: lo que se escribió sigue ahí para corregirlo.
      setFeedback({ tone: 'error', text: errorMessage(toError(err)) });
      return;
    }

    setEmail('');
    setAccountCheck(null);
    setSending(false);
    setFeedback({ tone: 'ok', text: INVITE_REGISTERED });
    await refresh();
  }

  async function handleResend(invitationId: string) {
    setFeedback(null);
    setBusy(true);

    try {
      await resendInvitation(invitationId);
    } catch (err: unknown) {
      setBusy(false);
      setFeedback({ tone: 'error', text: errorMessage(toError(err)) });
      return;
    }

    setBusy(false);
    setFeedback({ tone: 'ok', text: RESEND_OK });
    await refresh();
  }

  /** Abrir el diálogo borra el error de la vez anterior. */
  function handleRemove(member: TeamMember) {
    setRemoveError(null);
    setPendingMember(member);
  }

  function handleCancelRemove() {
    setPendingMember(null);
    setRemoveError(null);
  }

  async function handleConfirmRemove() {
    if (pendingMember === null) return;

    setRemoveError(null);
    setBusy(true);

    try {
      await removeMember(pendingMember.id);
    } catch (err: unknown) {
      // El diálogo SIGUE abierto con el motivo: cerrarlo dejaría al ADMIN sin
      // saber si el usuario se fue o no.
      setBusy(false);
      setRemoveError(errorMessage(toError(err)));
      return;
    }

    setBusy(false);
    setPendingMember(null);
    await refresh();
  }

  if (!isAdmin) {
    return (
      <div className={styles.screen}>
        <p className={styles.alert}>{NOT_ADMIN}</p>
      </div>
    );
  }

  const full = limitReached(team, invitations);
  const emailTaken =
    accountCheck !== null && accountCheck.email === email && accountCheck.hasAccount;
  const canSend =
    isValidEmail(email) && !full && !sending && !checking && !emailTaken && !busy;
  const dots = capacityDots(team, invitations);

  return (
    <div className={styles.screen}>
      {loading ? (
        <p className={styles.status} role="status">
          {LOADING}
        </p>
      ) : loadError !== null ? (
        <p className={styles.alert} role="alert">
          {loadError}
        </p>
      ) : (
        <div className={styles.content}>
          <p className={styles.eyebrow}>Módulo 01 · Onboarding</p>
          <h1 className={styles.title}>Gestión de invitaciones</h1>
          <p className={styles.subtitle}>
            Invita a los usuarios de tu organización. Cada nuevo usuario se incorporará con rol{' '}
            <strong>Editor</strong>
            {'. Límite: 5 usuarios por organización.'}
          </p>

          <div className={styles.capacityRow}>
            <div className={styles.dots} data-testid="capacity-dots">
              {dots.map((dot, index) => (
                <span
                  key={index}
                  className={`${styles.dot} ${DOT_CLASS[dot]}`}
                  title={DOT_TITLE[dot]}
                />
              ))}
            </div>
            <span className={styles.count} data-testid="capacity-count">
              {capacityLabel(team)}
            </span>
            <span className={styles.detail} data-testid="capacity-detail">
              {capacityDetail(team, invitations)}
            </span>
          </div>

          {/* Solo con las cinco plazas ocupadas. El texto se importa: es el de la
              spec, verbatim, y no se reescribe aquí. */}
          {full && (
            <p className={styles.notice} role="note">
              <svg
                className={styles.noticeIcon}
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <circle cx="12" cy="12" r="10" />
                <line x1="12" y1="8" x2="12" y2="12" />
                <line x1="12" y1="16" x2="12.01" y2="16" />
              </svg>
              {LIMIT_NOTICE}
            </p>
          )}

          <div className={styles.card}>
            <h2 className={styles.cardTitle}>Invitar nuevo usuario</h2>
            <div className={styles.inviteRow}>
              <input
                className={styles.input}
                type="email"
                aria-label="Email del nuevo usuario"
                placeholder="email@empresa.com"
                autoComplete="email"
                value={email}
                onChange={handleEmailChange}
                disabled={full || sending}
              />
              <button
                type="button"
                className={styles.button}
                onClick={handleSend}
                disabled={!canSend}
              >
                Enviar invitación
              </button>
            </div>

            {/* El aviso va bajo el campo y solo si el resultado corresponde al
                texto que hay AHORA en el campo. */}
            {emailTaken && (
              <p className={styles.fieldError} role="alert">
                {ACCOUNT_EXISTS}
              </p>
            )}

            {feedback !== null && (
              <p
                className={feedback.tone === 'ok' ? styles.feedbackOk : styles.feedbackError}
                role={feedback.tone === 'ok' ? 'status' : 'alert'}
              >
                {feedback.text}
              </p>
            )}
          </div>

          <InvitationTables
            invitations={invitations}
            team={team}
            selfId={profile.id}
            busy={busy}
            onResend={handleResend}
            onRemove={handleRemove}
          />

          {pendingMember !== null && (
            <RemoveMemberDialog
              member={pendingMember}
              busy={busy}
              error={removeError}
              onConfirm={handleConfirmRemove}
              onCancel={handleCancelRemove}
            />
          )}
        </div>
      )}
    </div>
  );
}

// -----------------------------------------------------------------------------
// Constantes de presentación
// -----------------------------------------------------------------------------

/** Los títulos de los cinco puntos, tal como los pide la spec. */
const DOT_TITLE: Record<CapacityDot, string> = {
  used: 'Usuario activo',
  inv: 'Invitación pendiente',
  free: 'Plaza libre',
};

const DOT_CLASS: Record<CapacityDot, string> = {
  used: styles.dotUsed,
  inv: styles.dotInv,
  free: styles.dotFree,
};

const LOADING = 'Cargando invitaciones…';
const NOT_ADMIN = 'Esta pantalla es solo para administradores.';
const ACCOUNT_EXISTS = 'Este email ya tiene cuenta en Bearingworld.io.';
/**
 * «REGISTRADA», no «enviada»: no hay proveedor de correo en el proyecto ni flujo
 * de registro por invitación. Prometer un email sería afirmar algo que no pasa.
 */
const INVITE_REGISTERED =
  'Invitación registrada. El envío del correo de invitación llega con el flujo de registro por invitación.';
const RESEND_OK = 'Invitación reenviada.';

function toError(err: unknown): Error {
  return err instanceof Error ? err : new Error(String(err));
}

