/* =============================================================================
   INVT-01 · Confirmación de eliminación. Ningún color literal: tokens.css.
   ========================================================================== */

/* Cubre el panel entero, por encima del shell. */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--bw-sidebar-overlay);
}

.dialog {
  width: 100%;
  max-width: 420px;
  padding: 28px;
  border-radius: 6px;
  background: var(--bw-warm-cream);
  box-shadow: 0 20px 60px var(--bw-sidebar-overlay);
}

.title {
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: 17px;
  color: var(--bw-deep-steel);
  margin: 0 0 8px;
}

.person {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0 0 14px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.name {
  font-weight: 600;
  color: var(--bw-ink-steel);
}

.email {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.warning {
  padding: 10px 12px;
  border-left: 3px solid var(--bw-danger);
  border-radius: 0 var(--bw-radius) var(--bw-radius) 0;
  background: var(--bw-sensitive-bg);
  font-size: 12px;
  line-height: 1.5;
  color: var(--bw-error-text);
  margin: 0 0 20px;
}

.error {
  font-size: 12px;
  color: var(--bw-error-text);
  margin: 0 0 16px;
}

.actions {
  display: flex;
  gap: 10px;
}

.cancel {
  flex: 1;
  padding: 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: background 0.15s;
}

.cancel:hover:not(:disabled) {
  background: var(--bw-cold-white);
}

.confirm {
  flex: 1;
  padding: 10px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-danger);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-warm-cream);
  cursor: pointer;
  transition: background 0.15s;
}

.confirm:hover:not(:disabled) {
  background: var(--bw-sensitive-text);
}

.cancel:disabled,
.confirm:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

import { useEffect, useRef } from 'react';
import type { TeamMember } from '../../lib/invitations';
import styles from './RemoveMemberDialog.module.css';

interface Props {
  member: TeamMember;
  busy: boolean;
  error: string | null;
  onConfirm: () => void;
  onCancel: () => void;
}

/**
 * La confirmación de «Eliminar usuario» de INVT-01.
 *
 * Presentacional: no elimina nada, avisa a quien la abrió. La acción es
 * irreversible —el usuario pierde el acceso en el acto— y por eso no se
 * confirma con un `window.confirm` ni con un clic fuera: solo con el botón.
 */
export function RemoveMemberDialog({ member, busy, error, onConfirm, onCancel }: Props) {
  const cancelRef = useRef<HTMLButtonElement>(null);

  /** Escape cancela. Se registra en `document` y se retira al desmontar. */
  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') onCancel();
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onCancel]);

  /** Al abrirse, el foco va a `Cancelar`: el botón seguro, no el que destruye. */
  useEffect(() => {
    cancelRef.current?.focus();
  }, []);

  return (
    <div className={styles.overlay}>
      <div className={styles.dialog} role="dialog" aria-modal="true" aria-labelledby={TITLE_ID}>
        <h2 id={TITLE_ID} className={styles.title}>
          Eliminar usuario
        </h2>

        <p className={styles.person}>
          <span className={styles.name}>{member.fullName}</span>
          <span className={styles.email}>{member.email}</span>
        </p>

        <p className={styles.warning}>
          Esta acción es irreversible. El usuario perderá acceso inmediatamente.
        </p>

        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}

        <div className={styles.actions}>
          <button
            ref={cancelRef}
            type="button"
            className={styles.cancel}
            onClick={onCancel}
            disabled={busy}
          >
            Cancelar
          </button>
          <button
            type="button"
            className={styles.confirm}
            onClick={onConfirm}
            disabled={busy}
          >
            Eliminar
          </button>
        </div>
      </div>
    </div>
  );
}

/** Un solo diálogo vive a la vez: un id fijo basta y no depende de `useId`. */
const TITLE_ID = 'remove-member-dialog-title';
